public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_ValidOctal() {
        byte[] buffer = " 000123 ".getBytes();
        // offset 0, length 8. Result should be 83 (octal 123)
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, 8));
    }
























}

